<!DOCTYPE html>
<html>
<head>
<title>Simple Desktop Environment</title>
<style>
#desktop {
  width: 800px;
  height: 600px;
  background-color: #2e3440; /* Dark theme */
  border: 1px solid #434c5e;
  margin: 0 auto;
  padding: 10px;
  box-sizing: border-box;
}

#taskbar {
  width: 800px;
  height: 30px;
  background-color: #434c5e;
  position: sticky;
  top: 0;
  left: 0;
  z-index: 10; /* Ensure it's above windows */
}

#open-files {
  width: 60px;
  height: 24px;
  background-color: #3b4252;
  border: none;
  cursor: pointer;
  margin-right: 10px;
}

#open-notepad {
  width: 60px;
  height: 24px;
  background-color: #3b4252;
  border: none;
  cursor: pointer;
}

.win-close {
  position: absolute;
  top: 0;
  right: 0;
  width: 20px;
  height: 20px;
  background-color: #e06c75;
  border: none;
  cursor: pointer;
}

.fs-item {
  margin: 5px;
  padding: 3px;
  border: 1px solid #434c5e;
  background-color: #3b4252;
  cursor: pointer;
}

.fs-item:hover {
  background-color: #556176;
}

#files-path {
  margin-bottom: 10px;
}

#tabs {
    display: flex;
    height: 30px;
    border-bottom: 1px solid #434c5e;
}

.tab {
    background-color: #434c5e;
    color: white;
    padding: 5px 10px;
    cursor: pointer;
    flex-shrink: 0; /* Prevent tabs from shrinking */
}

.tab.active {
  background-color: #2e3440;
}

#editor {
  width: 680px;
  height: 450px;
  border: 1px solid #434c5e;
  padding: 10px;
  font-family: monospace;
  resize: vertical; /* Allow vertical resizing */
}

/* Window Styles (Basic) */
.win {
    width: 400px;
    height: 300px;
    position: absolute;
    background-color: #2e3440;
    border: 1px solid #434c5e;
    padding: 10px;
}

</style>
</head>
<body>

<div id="desktop">
  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>

  <div id="files-path">/</div>
  <div id="files-content">
    <div class="fs-item" onclick="loadFile('/bin')">bin</div>
    <div class="fs-item" onclick="loadFile('/etc')">etc</div>
    <div class="fs-item" onclick="loadFile('/home')">home</div>
    <div class="fs-item" onclick="loadFile('/usr')">usr</div>
    <div class="fs-item" onclick="loadFile('/var')">var</div>

    <div class="fs-item" onclick="loadFile('/home/user')">user</div>
    <div class="fs-item" onclick="loadFile('/home/user/Documents')">Documents</div>
    <div class="fs-item" onclick="loadFile('/home/user/Downloads')">Downloads</div>
    <div class="fs-item" onclick="loadFile('/home/user/Pictures')">Pictures</div>
  </div>

  <div id="files-up"></div>

  <!-- Files Window -->
  <div id="files-window" style="display: none;">
    <div id="files-path">/</div>
    <div id="files-content">
      <div class="fs-item" onclick="loadFile('/bin')">bin</div>
      <div class="fs-item" onclick="loadFile('/etc')">etc</div>
      <div class="fs-item" onclick="loadFile('/home')">home</div>
      <div class="fs-item" onclick="loadFile('/usr')">usr</div>
      <div class="fs-item" onclick="loadFile('/var')">var</div>

      <div class="fs-item" onclick="loadFile('/home/user')">user</div>
      <div class="fs-item" onclick="loadFile('/home/user/Documents')">Documents</div>
      <div class="fs-item" onclick="loadFile('/home/user/Downloads')">Downloads</div>
      <div class="fs-item" onclick="loadFile('/home/user/Pictures')">Pictures</div>
    </div>
    <div id="files-up"></div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" style="display: none;">
    <ul id="tabs">
      <li class="tab active"><span id="new-tab">New Tab</span></li>
    </ul>
    <textarea id="editor"></textarea>
  </div>
</div>

<script>
const desktop = document.getElementById('desktop');
const taskbar = document.getElementById('taskbar');
const openFilesButton = document.getElementById('open-files');
const openNotepadButton = document.getElementById('open-notepad');
const filesPathDisplay = document.getElementById('files-path');
const filesContent = document.getElementById('files-content');
const filesUpButton = document.getElementById('files-up');
const filesWindow = document.getElementById('files-window');
const notepadWindow = document.getElementById('notepad-window');
const editor = document.getElementById('editor');
const tabs = document.getElementById('tabs');
const newTabButton = document.getElementsByClassName('tab')[0];

let currentPath = '/';

function loadFile(path) {
  currentPath = path;
  filesPathDisplay.innerText = currentPath;
  if (path === '/') {
    filesContent.innerHTML = '<div>bin</div><div>etc</div><div>home</div><div>usr</div><div>var</div><div >user</div><div>Documents</div><div>Downloads</div><div>Pictures</div>';
    filesUpButton.style.display = 'none'; // Hide up button when at root
  } else if (path === '/home/user') {
     filesContent.innerHTML = '<div>bin</div><div>etc</div><div>home</div><div>usr</div><div>var</div><div >user</div><div>Documents</div><div>Downloads</div><div>Pictures</div>';
      filesUpButton.style.display = 'inline';
  }
   else {
    filesContent.innerHTML = '';
    // Simulate loading files from the path (replace with actual file loading logic)
    const fsItems = `
      <div class="fs-item" onclick="loadFile('${path}/bin')">bin</div>
      <div class="fs-item" onclick="loadFile('${path}/etc')">etc</div>
      <div class="fs-item" onclick="loadFile('${path}/home')">home</div>
      <div class="fs-item" onclick="loadFile('${path}/usr')">usr</div>
      <div class="fs-item" onclick="loadFile('${path}/var')">var</div>
    `;
    filesContent.innerHTML = fsItems;
     filesUpButton.style.display = 'inline'; // Show up button for subdirectories

  }


}

function goUp() {
  const parts = currentPath.split('/');
  if (parts.length > 1) {
    const newPath = parts.slice(0, -1).join('/');
    loadFile(newPath);
  }
}

openFilesButton.addEventListener('click', () => {
  filesWindow.style.display = 'block';
  notepadWindow.style.display = 'none';
});

openNotepadButton.addEventListener('click', () => {
  filesWindow.style.display = 'none';
  notepadWindow.style.display = 'block';
  editor.value = ''; // Clear the editor on new tab
});


newTabButton.addEventListener('click', () => {
    editor.value = '';
    tabs.firstChild.classList.remove("active");
    const newTab = document.createElement("li");
    newTab.className = "tab active";
    newTab.innerHTML = "<span id=\"new-tab\">New Tab</span>";
    tabs.appendChild(newTab);

});


</script>

</body>
</html>
